$('start').onclick=toggle;$('heroStart').onclick=toggle;$('reset').onclick=reset;$('swap').onclick=()=>{swap=!swap;reset();};$('seed').onchange=reset;for(let i=0;i<5;i++)$('pick'+i).onchange=()=>{const count=$('mode').value==='pvp'?Math.max(2,Math.min(5,Number($('playerCount').value)||3)):2;for(let j=0;j<count;j++)if(j!==i&&$('pick'+j).value===$('pick'+i).value)$('pick'+j).value=Object.keys(names).find(id=>!Array.from({length:count},(_,k)=>k).filter(k=>k!==j).map(k=>$('pick'+k).value).includes(id));reset();};$('record').onclick=()=>{if(tournament.live){tournament.setView(!tournament.clean);return;}document.body.classList.toggle('cinema');$('record').textContent=document.body.classList.contains('cinema')?'↙ Thoát chế độ quay':'⛶ Chế độ quay';};document.addEventListener('keydown',e=>{if(e.code==='Space'&&((tournament.live&&tournament.clean)||!['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName))){e.preventDefault();toggle();}if(e.code==='Escape'){document.body.classList.remove('cinema');tournament.setView(false);}});document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.stop();music.pause();}if(document.hidden&&tournament.active&&!tournament.paused)tournament.toggle();else if(document.hidden&&running)toggle();});

