function circle(x,y,r,color,width=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function floor(){if(duel.arena.layout==='portrait')return;const a=duel.arena,image=images.arena;if(image?.complete&&image.naturalWidth)ctx.drawImage(image,a.left,a.top,a.width,a.height);else{ctx.fillStyle='#34464e';ctx.fillRect(a.left,a.top,a.width,a.height);}}


