function drawBlueEffect(row,frame,x,y,scale=1,intro=false,angle=0){const im=images[intro?'goku_blue_intro_vfx':'goku_blue_vfx'];if(!im?.complete||!im.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);ctx.drawImage(im,Math.max(0,Math.min(5,frame))*512,row*384,512,384,-256,-192,512,384);ctx.restore();}
