function drawFriezaEffect(action,frame,x,y,scale=1,angle=0){const im=images.frieza_vfx;if(!im?.complete||!im.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);ctx.drawImage(im,Math.min(5,frame)*512,(({deathbeam:0,saucers:1,supernova:2,golden:3})[action]??0)*384,512,384,-256,-192,512,384);ctx.restore();}
function drawLuffyEffect(action,frame,x,y,scale=1,angle=0,stretch=1){const im=images.luffy_vfx;if(!im?.complete||!im.naturalWidth)return;const row=({pistol:0,gatling:1,redhawk:2,gear2:3})[action]??0;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*stretch,scale);ctx.drawImage(im,Math.max(0,Math.min(5,frame))*512,row*384,512,384,-256,-192,512,384);ctx.restore();}
function drawGogetaEffect(action,frame,x,y,scale=1,angle=0,face=1){const im=images.gogeta_vfx;if(!im?.complete||!im.naturalWidth)return;const row=({bigbang:0,stardust:1,meteor:2,stardustfall:3})[action]??2;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(7,frame))*512,row*384,512,384,-256,-192,512,384);ctx.restore();}
